let img, SZE;
let clrHue, clrHueDevi, flipHueTxt;

function preload() {
  img = loadImage("https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Copper_and_alloy_group_of_wrestlers_%282nd_%E2%80%93_1st_cent._B.C.%29_in_the_National_Archaeological_Museum_of_Athens_on_16_May_2018.jpg/682px-Copper_and_alloy_group_of_wrestlers_%282nd_%E2%80%93_1st_cent._B.C.%29_in_the_National_Archaeological_Museum_of_Athens_on_16_May_2018.jpg");
}

function setup() {
  // createCanvas(800, 480, WEBGL);
  createCanvas(windowWidth, windowHeight, WEBGL);
	frameRate(30);
	describe("random planes either textured or base on the horizontal position")
  texture(img);
  background(0, 0, 8);
	noStroke();
	sphere(max(width, height));
	colorMode(HSB);
	clrHue = ~~random(360);
	clrHueDevi = ~~random(20, 60);
	flipHueTxt = random() < 0.5;
}

function draw() {
  // orbitControl();
  // if (frameCount > 2000) // noLoop() removed for animation
  const x = randomGaussian(0, width / 2);
  const y = randomGaussian(0, height / 4);
  const w = ~~abs(random(width / 12, width / 3));
  const h = ~~(w / random(.75, 2));
  rect3D(x, y, w, h);
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}

function rect3D(x, y, w, h) {
  push()
	if (abs(x) < w/2) x = Math.sign(x) * w/3; // x pos correction to reduce overlapping; w/2 keeps empty spot in the mid
  translate(x, y, -random(width, height));
  rotateY(Math.sign(x) * 0.6);
	const hue1 = (clrHue + random(-0.5, 0.5) * clrHueDevi) % 360;
	const hue2 = (clrHue + random(-0.5, 0.5) * clrHueDevi + 180) % 360;
  if (random()<0.5) {
		// depends on horizontal position
		fill(color(x < 0 ? hue1 : hue2, random(55, 95),random(45, 85)));
	} else {  	
		// opposite hue for picture than planes
		let hue = flipHueTxt ? hue2 : hue1;
		if (x > 0 ) hue = flipHueTxt ? hue1 : hue2;
		tint(color(hue, random(10, 20), random(90, 100)));
  }
  plane(w, h);
  pop();
}
